/**
 * Which maintenance-page code a risd process is RUNNING, versus what is on disk now.
 *
 * Why this exists: `/ui` is generated by the daemon from modules that Node imported
 * once at startup, so editing `ui.js` (or any daemon module) and reloading the page
 * does NOT show the new code — the process still runs the old module. The browser
 * cache is already handled (`cache-control: no-store`, the page embeds everything),
 * so the only stale layer is the daemon's own module graph. This stamp names both
 * layers: `loaded` is taken at startup, `disk` is recomputed per request. The page
 * reloads itself when `loaded` changes (a restarted daemon = new page code) and
 * shows a 「重启 daemon 生效」 hint while the two disagree (edited but not reloaded).
 *
 * The stamp is filesystem metadata only (size + mtime), never file contents: fifteen
 * `statSync` calls per health poll are free, hashing fifteen sources is not. A
 * same-size edit made within the same mtime tick could in theory hide a change, which
 * is the same assumption the dsh host's own client-module revision makes.
 *
 * @module dsh-risd/build
 */
import { createHash } from 'node:crypto'
import { statSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

/** Daemon modules whose code the maintenance page renders: a change means restart. */
export const UI_SOURCE_FILES = [
  'server.js',
  'ui.js',
  'ping.js',
  'lifecycle.js',
  'programs.js',
  'debug.js',
  'view.js',
  'state.js',
  'log.js',
  'leases.js',
  'git.js',
  '../proxy.js',
  '../proxybridge-bundle.js',
  '../janitor.js',
  '../redirector.js',
  '../startup.js',
]

const HERE = fileURLToPath(new URL('.', import.meta.url))

/**
 * `/v1/health` reports `disk` on every poll, and the page polls it every few
 * seconds. Sixteen `statSync` calls per poll are cheap but pointless: the daemon
 * code cannot change under a running process (a change only takes effect after a
 * restart), so a short cache is invisible to the page (allowed to lag up to 5 s).
 */
export const BUILD_STAMP_TTL_MS = 5000

let cachedStamp = { value: '', at: 0 }

/**
 * Identify the daemon code currently on disk.
 *
 * @returns {string} 12 hex chars; stable while the files are, changes with any edit.
 */
export function buildStamp() {
  const now = Date.now()
  if (cachedStamp.value !== '' && now - cachedStamp.at < BUILD_STAMP_TTL_MS) return cachedStamp.value
  const hash = createHash('sha1')
  for (const name of UI_SOURCE_FILES) {
    hash.update(name)
    hash.update('\0')
    try {
      const stat = statSync(new URL(name, new URL('.', import.meta.url)))
      hash.update(String(stat.size))
      hash.update(':')
      hash.update(String(stat.mtimeMs))
    } catch {
      // A file that is not there (a trimmed install) must not make the stamp throw;
      // the name alone still participates, so adding it later changes the stamp.
      hash.update('absent')
    }
    hash.update('\n')
  }
  const value = hash.digest('hex').slice(0, 12)
  cachedStamp = { value, at: now }
  return value
}

/** Drop the cache (tests that copy the daemon modules and mutate their mtimes). */
export const __test = {
  resetBuildStampCache() { cachedStamp = { value: '', at: 0 } },
}

/** The directory the daemon modules live in (exposed for tests that touch a copy). */
export const UI_SOURCE_DIR = HERE
